<section class="card form-card" id="notification-preferences"><h2 class="form-section-title">A nudge, not a noise.</h2><p class="form-section-description">Choose what you hear about. In-app notifications don’t depend on email delivery.</p><form action="<?= e(route_url('/api/settings/notifications')) ?>" method="post" data-api><?= csrfField() ?><?php foreach(['study'=>['Study sessions','Reminders for your preferred study days.'],'streak'=>['Streak reminders','A little encouragement to keep your rhythm.'],'deadlines'=>['Assignment deadlines','A reminder before an upcoming due date.'],'feedback'=>['Your feedback and results','Know when a reviewer has responded.'],'milestones'=>['Milestones & achievements','Celebrate the small things you earned.'],'weekly'=>['Weekly reflections','A report based on your recorded activity.'],'email'=>['Also send by email','Only available when SMTP email delivery is configured.']] as $key=>[$label,$desc]): ?><label class="switch-row"><div><strong style="font-size:12px;font-weight:500"><?= $label ?></strong><p><?= $desc ?></p></div><input class="switch" type="checkbox" name="<?= $key ?>" value="1" aria-label="<?= $label ?>" <?= !empty($notifications[$key])?'checked':'' ?>></label><?php endforeach; ?><div class="form-actions"><button class="btn btn-primary">Save notification preferences</button></div></form><div class="separator"></div><button class="btn btn-secondary btn-small" data-browser-notifications type="button"><?= icon('bell',15) ?> Browser notification permission</button><p class="fine-print" style="margin-top:12px">Background push delivery is not configured in this build. Permission does not mean notifications will be delivered outside your in-app inbox.</p></section><?php endif; ?></div>
